"""Export a self-contained Python reproducer requiring only PyTorch."""

import inspect
import json
import textwrap
from pathlib import Path
from string import Template

from . import portable
from .environment import describe
from .finding import seal_bundle
from .lowering import build, freeze
from .storage import atomic_json

_CURRENT_ENVIRONMENT = object()

REPRO = Template('''#!/usr/bin/env python3
"""Generated by Faultline. This case is $label.

Run: python repro.py
Optional: python repro.py --native-minifier
The native minifier is PyTorch's separate debugger; Faultline's IR reducer does
not claim to extend its internal implementation. Mutants validate the harness.
Exit 0: agreement; 1: stable discrepancy/error; 2: inconclusive/unavailable.
"""
import argparse
import json
import os
import sys

CASE = json.loads($case_json)
SETTINGS = json.loads($settings_json)
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--device", default=SETTINGS["device"])
parser.add_argument("--native-minifier", action="store_true")
options = parser.parse_args()
if options.native_minifier:
    os.environ["TORCHDYNAMO_REPRO_AFTER"] = "aot"
    os.environ["TORCHDYNAMO_REPRO_LEVEL"] = "4"
os.environ.setdefault("TORCHINDUCTOR_COMPILE_THREADS", "1")
import torch

class Reference(torch.nn.Module):
$reference

class Candidate(torch.nn.Module):
$candidate

def make_inputs():
    result = []
    for spec in CASE["inputs"]:
        dtype = getattr(torch, spec["dtype"])
        shape = spec["shape"]
        value = torch.tensor(spec["values"], dtype=dtype, device=options.device).reshape(shape)
        if spec["layout"] == "transposed":
            value = value.transpose(-1, -2).contiguous().transpose(-1, -2)
        elif spec["layout"] == "strided":
            backing = torch.empty((*shape[:-1], shape[-1] * 2), dtype=dtype, device=options.device)
            target = backing[..., ::2]
            target.copy_(value)
            value = target
        elif spec["layout"] == "expanded":
            value = value[..., :1].contiguous().expand(shape)
        result.append(value)
    return tuple(result)

# The same predicate source is embedded in full; no Faultline import is needed.
$predicate

EXPECTED = json.loads($expected_json)
CASE_HASH = $case_hash


def finish(record):
    result = {"schema_version": 1, "case_hash": CASE_HASH, "torch_version": torch.__version__,
              "device": options.device, "backend": SETTINGS["backend"],
              "injected_fault": SETTINGS["backend"].startswith("mutant:"),
              "rtol": $rtol, "atol": $atol, "repeats": SETTINGS["repeats"], **record}
    result["fingerprint"] = fingerprint(result)
    if EXPECTED is not None:
        result["reproduces_expected"] = same_failure(EXPECTED, result)
    print(json.dumps(result, allow_nan=False))
    if EXPECTED is not None and not result["reproduces_expected"]:
        return 2
    return 0 if result["status"] == "pass" else (1 if result["status"] in REDUCIBLE else 2)


def main():
    unavailable = configure(options.device, SETTINGS["threads"], CASE["seed"])
    if unavailable:
        return finish(unavailable)
    backend = SETTINGS["backend"]
    mutant = backend.split(":", 1)[1] if backend.startswith("mutant:") else None

    def create_candidate():
        if mutant == "crash":
            raise RuntimeError("Injected compiler failure: faultline validation fixture")
        candidate = Candidate()
        if backend != "eager" and mutant is None:
            candidate = torch.compile(candidate, backend=backend, fullgraph=True, dynamic=False)
        return candidate

    with torch.inference_mode():
        try:
            inputs = make_inputs()
            reference = Reference()
        except Exception as exc:
            return finish(exception_record(exc, "reference_error"))
        record, _, _ = check_execution(
            reference, create_candidate, inputs, device=options.device,
            repeats=SETTINGS["repeats"], rtol=$rtol, atol=$atol, mutant=mutant,
        )
        return finish(record)

if __name__ == "__main__":
    sys.exit(main())
''')


def export_case(case, settings, directory, result=None, *, environment=_CURRENT_ENVIRONMENT):
    """Export fresh local results, or supply their historical execution environment.

    An explicit None preserves unknown provenance instead of inventing it from
    the exporting machine. Omitting the argument records the current machine.
    """
    from .oracle import tolerances

    settings.validate()
    if settings.backend in {"mutant:hang", "mutant:worker-exit"}:
        raise ValueError("Process-control fixtures are not exported as reproducers")
    directory = Path(directory)
    if directory.exists() and any(directory.iterdir()):
        raise ValueError("Export would overwrite existing evidence; choose a new directory")
    case = freeze(case)
    mutant = settings.backend.split(":", 1)[1] if settings.backend.startswith("mutant:") else None
    rtol, atol = tolerances(case.inputs[0].dtype, settings.rtol, settings.atol)
    if result and (
        result.get("case_hash") != case.digest()
        or result.get("backend") != settings.backend
        or result.get("device") != settings.device
        or result.get("injected_fault") != bool(mutant)
        or any(
            result.get(key, value) != value
            for key, value in {
                "rtol": rtol,
                "atol": atol,
                "repeats": settings.repeats,
            }.items()
        )
    ):
        raise ValueError("Export settings or inputs do not match the recorded outcome")
    expected = result if result and result["status"] in portable.REDUCIBLE else None
    code = REPRO.substitute(
        predicate=inspect.getsource(portable),
        expected_json=repr(json.dumps(expected, allow_nan=False)),
        case_hash=repr(case.digest()),
        label="a CONTROLLED FAULT INJECTION" if mutant else "an unconfirmed differential test",
        case_json=repr(json.dumps(case.to_dict(), allow_nan=False)),
        settings_json=repr(json.dumps(settings.to_dict(), allow_nan=False)),
        reference=textwrap.indent(build(case).code.strip(), "    "),
        candidate=textwrap.indent(build(case, mutant).code.strip(), "    "),
        rtol=repr(rtol),
        atol=repr(atol),
    )
    compile(code, "repro.py", "exec")
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "repro.py").write_text(code, encoding="utf-8")
    atomic_json(directory / "case.json", case.to_dict())
    atomic_json(directory / "settings.json", settings.to_dict())
    atomic_json(
        directory / "environment.json",
        describe() if environment is _CURRENT_ENVIRONMENT else environment,
    )
    if result:
        atomic_json(directory / "outcome.json", result)
        seal_bundle(directory)
    return directory / "repro.py"
